INSERT INTO changelog (title, body, created_at) VALUES
('Стартапи: опори стали системою',
'Замість анкети з блоків — робочі інструменти, повʼязані між собою.
ІДЕЯ: формула одним реченням (Для кого / біль / продукт / що дає / на відміну від / ми) — бачиш речення наживо, кожне збереження = нова версія в історії; альтернативи (ціна, сильне, слабке); стрес-тест — 7 критеріїв з оцінкою 1–5 і «чому», шкала міцності і вердикт (кнопка «Джері, атакуй ідею»); докази — журнал розмов з клієнтами з лічильниками «підтвердили біль» і «готові платити», сценарій розмови від Джері.
МАРКЕТИНГ: сегменти з болем їхніми словами і оффером (результат, термін, гарантія, ціна); кути/гачки дошкою (ідеї → тестуємо → працює / не зайшло) з фактом; канали з бюджетом і ціною ліда (план і факт); воронка — кроки з % переходу і ціль клієнтів → скільки треба лідів, бюджет і ціна клієнта, рахує вживу.
ТЕХНІЧНА: карта модулів зі статусами і релізами; інфраструктура чеклістом (сервер, домен, база і бекапи, деплой і оновлення, міграції, моніторинг, вхід, пошта, оплата, аналітика, ШІ) — вибір, ціна, «налаштовано»; релізи v0.1/v0.2… — у кожного свій промпт для Claude Code (копіюєш і віддаєш по черзі); CLAUDE.md проєкту.
ФІНАНСИ: тумблери «клієнти і реклама — з маркетингу» і «постійні витрати — з технічної» (цифри підтягуються самі), тарифи з часткою продажів, три сценарії (песимістичний / реальний / оптимістичний).
Над кожною опорою — кроки готовності і кнопка «Джері, збудуй». Старі тексти блоків лежать унизу кожної опори («Записи з попередньої версії») — Джері може перенести їх у нову структуру.',
'2026-10-31 23:00:00');
